'use client';

import { motion } from 'framer-motion';

const services = [
    { name: 'Rao Abdul Hadi', role: 'Web Architecture', desc: 'Scalable, high-performance web systems.' },
    { name: 'Rana Talha Jabbar', role: 'Mobile Ecosystems', desc: 'Seamless native and cross-platform experiences.' },
    { name: 'Muhammad Hafeez', role: 'Full Stack Systems', desc: 'End-to-end digital solutions.' },
    { name: 'Muhammad Huzaifa Hassan', role: 'DevOps & Infrastructure', desc: 'Resilient cloud architecture.' },
];

export default function ServiceCards() {
    return (
        <section id="architecture" className="py-24 px-6 md:px-20">
            <h2 className="text-3xl md:text-5xl font-heading font-bold mb-16 text-center tracking-tight text-white/90">
                THE ARCHITECTURE
            </h2>
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-4 gap-8">
                {services.map((service, index) => (
                    <motion.div
                        key={index}
                        whileHover={{ scale: 1.05, rotateX: 5, rotateY: 5 }}
                        transition={{ type: 'spring', stiffness: 300, damping: 20 }}
                        className="group relative p-8 h-64 border border-white/10 bg-white/5 backdrop-blur-sm rounded-lg overflow-hidden flex flex-col justify-end hover:border-gold/50 transition-colors"
                    >
                        <div className="absolute inset-0 bg-gradient-to-t from-black/80 to-transparent pointer-events-none" />
                        <div className="relative z-10">
                            <h3 className="text-xl font-bold font-heading text-white group-hover:text-gold transition-colors">{service.name}</h3>
                            <p className="text-sm font-bold text-blue-400 mt-1 uppercase tracking-wider">{service.role}</p>
                            <p className="text-xs text-gray-400 mt-2">{service.desc}</p>
                        </div>
                        {/* Hover Glow Effect */}
                        <div className="absolute -inset-2 bg-gold/20 blur-2xl opacity-0 group-hover:opacity-100 transition-opacity duration-500 rounded-full" />
                    </motion.div>
                ))}
            </div>
        </section>
    );
}
